class Point {
  final int x, y;
  const Point(this.x, this.y);
typedef Triangle = (int, int, int);
List<int> triangleSites(Triangle t) => [t.$1, t.$2, t.$3];
List<Edge> triangleEdges(Triangle t) => [
  (t.$1, t.$2),
  (t.$2, t.$3),
  (t.$3, t.$1),
];
  final List<Point> points;
  void add(Triangle t) {
    final sites = triangleSites(t), edges = triangleEdges(t);
    for (var i = 0; i < 3; i++) {
      directed[edges[i]] = sites[(i + 2) % 3];
    }
  }

  void remove(Triangle t) {
    for (final edge in triangleEdges(t)) {
      directed.remove(edge);
    }
